// @file ./experiments/dbgpt-excel-local.ts
import { defineExperiment } from "niceeval";
import { dbGptExcel } from "../agents/dbgpt-excel.ts";

export default defineExperiment({
  description: "DB-GPT spreadsheet analysis baseline against the local service",
  agent: dbGptExcel({
    baseUrl: "http://localhost:5670",
    fixturePath: "../docker/examples/excel/Walmart_Sales.csv",
  }),
  // This is the model name in configs/dbgpt-proxy-ollama.toml. It must be
  // available from that configured DB-GPT service before this experiment runs.
  model: "deepseek-r1:1.5b",
  attempts: 1,
});
// @file ./niceeval.config.ts
import { defineConfig } from "niceeval";

export default defineConfig({
  // Add experiments/ with defineExperiment(...) to run evals.
  //
  // Judge Facts require an Eval declaration: judge: true. Configure the model here or
  // on an Experiment. A consumed Fact without a model or key becomes unavailable and
  // makes that Attempt errored. Any OpenAI-compatible /chat/completions service works;
  // the key is read from OPENAI_API_KEY unless apiKeyEnv says otherwise.
  // judge: { model: "gpt-5.4-mini" },
});

// @file ./evals/walmart-sales.eval.ts
import { defineEval } from "niceeval";
import { pattern } from "niceeval/expect";

export default [
  defineEval({
    description: "Finds a concrete weekly-sales value from the uploaded spreadsheet",
    async test(t) {
      const turn = await t.send(
        "Using the uploaded sales spreadsheet, what is the Weekly_Sales value for Store 1 on 05-02-2010? Return the number and briefly identify the row used.",
      );

      turn.succeeded().label("Spreadsheet query completed");
      t.check(turn.message, pattern(/1[,.]?643[,.]?690(?:[,.]?9(?:0)?)?/))
        .label("Returns the fixture's Store 1 weekly-sales value");
    },
  }),
  defineEval({
    description: "Does not invent a value for a date absent from the spreadsheet",
    async test(t) {
      const turn = await t.send(
        "Using the uploaded sales spreadsheet, what is the Weekly_Sales value for Store 1 on 31-02-2010?",
      );

      turn.succeeded().label("Spreadsheet query completed");
      t.check(turn.message, pattern(/不存在|没有|无数据|无法|不能|未找到|查不到/i))
        .label("Explicitly declines to fabricate missing data");
    },
  }),
];

